}

questions.solution:
function makePoint(x, y) {
  function Point(horizontal, vertical) {
    this.x = horizontal;
    this.y = vertical;
  }
  Point.prototype.coordinates = function() { return [this.x, this.y]; };
  return new Point(x, y).coordinates();
}

